            cptr.stPtro(otmp, $obj_cobj, null);  /* contents handled above */
            cptr.stI16o(otmp, $obj_timed, 0);  /* not timed any more */
            cptr.stI32o(otmp, $obj_lamplit, 0);  /* caller handled lights */
